import { labelDayButton } from "react-day-picker";
import {
    useEffect, useRef, useState, type ComponentProps, type FormEvent,
} from "react";
import { Button } from "./button";
import { Calendar } from "./calendar";
import { formatCalendarDate, parseCalendarDate } from "./calendar-date";
import { cn } from "./utils";

type CalendarSchedule = {
    id: string;
    date: string;
    endDate?: string;
    title: string;
    taskId?: string;
    startTime?: string;
    endTime?: string;
    description?: string;
};

type CalendarScheduleReschedule = Pick<CalendarSchedule, "date"> & {
    endDate?: string;
    startTime?: string;
    endTime?: string;
};

type CalendarSchedulerProps = Omit<
    ComponentProps<"section">, "children"
> & {
    label: string;
    initialDate: string;
    events: readonly CalendarSchedule[];
    selectedDate?: string;
    onSelectedDateChange?: (date: string) => void;
    onEventSelect?: (event: CalendarSchedule) => void;
    onTaskSelect?: (taskId: string, event: CalendarSchedule) => void;
    onEventReschedule?: (
        event: CalendarSchedule,
        change: CalendarScheduleReschedule,
    ) => void | Promise<void>;
    onCreateEvent?: (date: string) => void;
    timeZone?: string;
    calendarLocale?: ComponentProps<typeof Calendar>["locale"];
    emptyMessage?: string;
};

const timePattern = /^([01]\d|2[0-3]):[0-5]\d$/;

function validateScheduleTime(
    eventId: string,
    startTime: string | undefined,
    endTime: string | undefined,
) {
    if ((startTime !== undefined && !timePattern.test(startTime)) ||
        (endTime !== undefined && (
            startTime === undefined ||
            !timePattern.test(endTime) ||
            endTime <= startTime
        ))) {
        throw new RangeError(
            `CalendarScheduler event has invalid time: ${eventId}`,
        );
    }
}

function CalendarScheduler({
    label,
    initialDate,
    events,
    selectedDate,
    onSelectedDateChange,
    onEventSelect,
    onTaskSelect,
    onEventReschedule,
    onCreateEvent,
    timeZone,
    calendarLocale,
    emptyMessage = "이 날짜에는 일정이 없습니다.",
    className,
    ...props
}: CalendarSchedulerProps) {
    if (typeof label !== "string" || !label.trim()) {
        throw new Error("CalendarScheduler requires a label.");
    }
    const initial = parseCalendarDate(initialDate);
    if (selectedDate !== undefined) parseCalendarDate(selectedDate);
    if (!Array.isArray(events)) {
        throw new Error("CalendarScheduler requires events.");
    }

    const ids = new Set<string>();
    for (const event of events) {
        if (!event || typeof event.id !== "string" ||
            !event.id.trim() || ids.has(event.id) ||
            typeof event.title !== "string" || !event.title.trim() ||
            typeof event.date !== "string") {
            throw new Error(
                "CalendarScheduler events need unique IDs, dates, and titles.",
            );
        }
        parseCalendarDate(event.date);
        if (event.endDate !== undefined) {
            parseCalendarDate(event.endDate);
            if (event.endDate < event.date) {
                throw new RangeError(
                    `CalendarScheduler event ends before it starts: ${event.id}`,
                );
            }
        }
        if (event.taskId !== undefined && !event.taskId.trim()) {
            throw new Error("CalendarScheduler task IDs cannot be empty.");
        }
        validateScheduleTime(event.id, event.startTime, event.endTime);
        ids.add(event.id);
    }
    if (events.some((event) => event.startTime !== undefined) &&
        !timeZone) {
        throw new Error("CalendarScheduler timed events need a timeZone.");
    }
    if (timeZone) {
        new Intl.DateTimeFormat("en", { timeZone });
    }

    const [internalDate, setInternalDate] = useState(initialDate);
    const [visibleMonth, setVisibleMonth] = useState(
        selectedDate === undefined ? initial : parseCalendarDate(selectedDate),
    );
    const currentDate = selectedDate === undefined
        ? internalDate : selectedDate;
    const [editing, setEditing] = useState<{
        eventId: string;
        date: string;
        endDate: string;
        startTime: string;
        endTime: string;
    } | null>(null);
    const [saving, setSaving] = useState(false);
    const [rescheduleError, setRescheduleError] = useState<string | null>(null);
    const rescheduleButton = useRef<HTMLButtonElement>(null);
    const recoveryRetryButton = useRef<HTMLButtonElement>(null);
    const visibleMonthStartDate = new Date(visibleMonth);
    visibleMonthStartDate.setDate(1);
    const visibleMonthEndDate = new Date(visibleMonthStartDate);
    visibleMonthEndDate.setMonth(visibleMonthEndDate.getMonth() + 1);
    visibleMonthEndDate.setDate(0);
    const visibleMonthStart = formatCalendarDate(visibleMonthStartDate);
    const visibleMonthEnd = formatCalendarDate(visibleMonthEndDate);
    const visibleMonthCounts = new Map<string, number>();
    for (const event of events) {
        const first = event.date < visibleMonthStart
            ? visibleMonthStart : event.date;
        const lastDate = event.endDate ?? event.date;
        const last = lastDate > visibleMonthEnd ? visibleMonthEnd : lastDate;
        if (first > last) continue;
        const date = parseCalendarDate(first);
        while (formatCalendarDate(date) <= last) {
            const key = formatCalendarDate(date);
            visibleMonthCounts.set(key,
                (visibleMonthCounts.get(key) ?? 0) + 1);
            date.setDate(date.getDate() + 1);
        }
    }
    const monthCount = [...visibleMonthCounts.values()].reduce(
        (count, total) => count + total, 0,
    );
    const dailyEvents = events.filter((event) =>
        event.date <= currentDate && (event.endDate ?? event.date) >= currentDate,
    ).sort((a, b) => {
        const byTime = (a.startTime ?? "").localeCompare(
            b.startTime ?? "",
        );
        return byTime || a.id.localeCompare(b.id);
    });
    const editingEvent = editing
        ? events.find((event) => event.id === editing.eventId) ?? null : null;
    const editingEventVisible = Boolean(editing && dailyEvents.some(
        (event) => event.id === editing.eventId,
    ));
    const monthPrefix = formatCalendarDate(visibleMonth).slice(0, 7);

    useEffect(() => {
        if (selectedDate !== undefined) {
            setVisibleMonth(parseCalendarDate(selectedDate));
        }
    }, [selectedDate]);

    useEffect(() => {
        if (!rescheduleError) return;
        if (editingEventVisible) rescheduleButton.current?.focus();
        else recoveryRetryButton.current?.focus();
    }, [rescheduleError, editingEventVisible]);

    function beginReschedule(event: CalendarSchedule) {
        setEditing({
            eventId: event.id,
            date: event.date,
            endDate: event.endDate ?? "",
            startTime: event.startTime ?? "",
            endTime: event.endTime ?? "",
        });
        setRescheduleError(null);
    }

    function updateEditing(patch: Partial<NonNullable<typeof editing>>) {
        setEditing((current) => current ? { ...current, ...patch } : current);
        setRescheduleError(null);
    }

    function cancelReschedule() {
        if (saving) return;
        setEditing(null);
        setRescheduleError(null);
    }

    async function attemptReschedule() {
        if (!editing || !onEventReschedule || saving) return;
        const original = events.find((item) =>
            item.id === editing.eventId);
        if (!original) {
            setRescheduleError("일정 원본을 찾을 수 없습니다.");
            return;
        }
        setRescheduleError(null);
        setSaving(true);
        try {
            parseCalendarDate(editing.date);
            const endDate = editing.endDate || undefined;
            if (endDate !== undefined) {
                parseCalendarDate(endDate);
                if (endDate < editing.date) {
                    throw new RangeError(
                        "종료 날짜는 시작 날짜보다 빠를 수 없습니다.",
                    );
                }
            }
            const startTime = editing.startTime || undefined;
            const endTime = editing.endTime || undefined;
            validateScheduleTime(original.id, startTime, endTime);
            if ((startTime !== undefined || endTime !== undefined) &&
                !timeZone) {
                throw new Error("시간 일정을 저장하려면 시간대가 필요합니다.");
            }
            await onEventReschedule(original, {
                date: editing.date,
                endDate,
                startTime,
                endTime,
            });
            setEditing(null);
        } catch (reason) {
            setRescheduleError(reason instanceof Error && reason.message.trim()
                ? reason.message
                : "일정을 저장하지 못했습니다. 다시 시도하세요.");
        } finally {
            setSaving(false);
        }
    }

    async function submitReschedule(event: FormEvent<HTMLFormElement>) {
        event.preventDefault();
        await attemptReschedule();
    }

    function selectDate(date: Date | undefined) {
        if (!date) return;
        const next = formatCalendarDate(date);
        setVisibleMonth(date);
        if (next === currentDate) return;
        if (selectedDate === undefined) setInternalDate(next);
        onSelectedDateChange?.(next);
    }

    return (
        <section aria-label={label} className={cn(
            "@container min-w-0 rounded-sm border border-border " +
            "bg-surface p-[var(--space-4)] text-foreground",
            className,
        )} {...props} data-ui="calendar-scheduler">
            <div data-slot="schedule-header"
                className="mb-[var(--space-3)] flex flex-wrap items-baseline gap-2">
                <h3 className="m-0 text-base font-semibold">{label}</h3>
                <span className="text-xs text-muted">
                    {monthPrefix} · {monthCount}건
                </span>
            </div>
            <div data-slot="schedule-layout"
                className="grid min-w-0 grid-cols-1 gap-[var(--space-4)] @2xl:grid-cols-2">
                <Calendar
                    mode="single" required
                    aria-label={`${label} 날짜`}
                    locale={calendarLocale}
                    navLayout="around"
                    disabled={saving ? () => true : undefined}
                    disableNavigation={saving}
                    classNames={{
                        month: "relative grid w-[15.75rem] max-w-full " +
                            "grid-cols-[2.25rem_minmax(0,1fr)_2.25rem] " +
                            "items-center gap-y-3 rdp-month",
                        month_grid: "col-span-3 w-full table-fixed border-collapse " +
                            "rdp-month_grid",
                    }}
                    month={visibleMonth}
                    onMonthChange={setVisibleMonth}
                    selected={parseCalendarDate(currentDate)}
                    onSelect={selectDate}
                    modifiers={{ scheduled: Array.from(
                        visibleMonthCounts.keys(), parseCalendarDate,
                    ) }}
                    modifiersClassNames={{
                        scheduled: "[&_button]:font-semibold " +
                            "[&_button]:underline " +
                            "[&_button]:decoration-accent " +
                            "[&_button]:decoration-2 " +
                            "[&_button]:underline-offset-4",
                    }}
                    labels={{
                        labelDayButton: (date, modifiers, options, dateLib) => {
                            const base = labelDayButton(
                                date, modifiers, options, dateLib,
                            );
                            const count = visibleMonthCounts.get(
                                formatCalendarDate(date),
                            ) ?? 0;
                            return count ? `${base}, 일정 ${count}건` : base;
                        },
                    }}
                />
                <div data-slot="schedule-agenda" role="region"
                    aria-label={`${currentDate} 일정`}
                    className="min-w-0 rounded-sm border border-border p-[var(--space-3)]">
                    <div className="flex flex-wrap items-center justify-between gap-2">
                        <h4 className="m-0 text-sm font-semibold">
                            {currentDate} 일정
                        </h4>
                        {onCreateEvent && (
                            <Button variant="outline"
                                onClick={() => onCreateEvent(currentDate)}>
                                일정 추가
                            </Button>
                        )}
                    </div>
                    {timeZone && (
                        <p className="m-0 mt-1 text-xs text-muted">
                            시간대: {timeZone}
                        </p>
                    )}
                    {editing && !editingEventVisible && (
                        <div data-slot="schedule-reschedule-recovery"
                            className={"mt-3 grid gap-2 rounded-sm border " +
                                "border-warning/40 bg-warning/10 p-3"}>
                            <p role={rescheduleError ? "alert" : "status"}
                                className="m-0 text-sm">
                                {rescheduleError ??
                                    `${editingEvent?.title ?? "일정"} 편집 초안이 ` +
                                    "다른 날짜에서 대기 중입니다."}
                            </p>
                            <div className="flex flex-wrap gap-2">
                                {editingEvent && (
                                    <Button variant="outline" disabled={saving}
                                        onClick={() => selectDate(
                                            parseCalendarDate(editingEvent.date),
                                        )}>
                                        일정 편집 날짜로 돌아가기
                                    </Button>
                                )}
                                {rescheduleError && editingEvent && (
                                    <button ref={recoveryRetryButton}
                                        type="button" disabled={saving}
                                        onClick={() => void attemptReschedule()}
                                        className={"rounded-sm border border-border " +
                                            "px-3 py-2 text-sm focus-visible:outline-2 " +
                                            "focus-visible:outline-focus disabled:opacity-50"}>
                                        재시도
                                    </button>
                                )}
                                <Button variant="ghost" disabled={saving}
                                    onClick={cancelReschedule}>
                                    취소
                                </Button>
                            </div>
                        </div>
                    )}
                    {dailyEvents.length === 0 ? (
                        <p role="status" className="my-[var(--space-4)] text-sm text-muted">
                            {emptyMessage}
                        </p>
                    ) : (
                        <ul className={
                            "m-0 mt-[var(--space-3)] list-none " +
                            "divide-y divide-border p-0"
                        }>
                            {dailyEvents.map((event) => {
                                const eventEditing =
                                    editing?.eventId === event.id
                                        ? editing : null;
                                const time = event.startTime
                                    ? `${event.startTime}${event.endTime
                                        ? `–${event.endTime}` : ""}`
                                    : "종일";
                                const range = event.endDate &&
                                    event.endDate !== event.date
                                    ? `${event.date}–${event.endDate}` : null;
                                const content = (
                                    <>
                                        <span className="text-xs text-muted">
                                            {time}
                                        </span>
                                        {range && <span className="text-xs text-muted">
                                            {range} · 여러 날짜 일정
                                        </span>}
                                        <strong className={
                                            "min-w-0 break-words text-sm " +
                                            "font-medium"
                                        }>
                                            {event.title}
                                        </strong>
                                        {event.description && (
                                            <span className={
                                                "min-w-0 break-words text-xs " +
                                                "text-muted"
                                            }>
                                                {event.description}
                                            </span>
                                        )}
                                    </>
                                );
                                return (
                                    <li key={event.id}>
                                        <div className="grid gap-2 py-2">
                                            {onEventSelect ? (
                                                <button data-slot="schedule-event"
                                                    type="button"
                                                    onClick={() =>
                                                        onEventSelect(event)}
                                                    className={
                                                        "grid w-full gap-1 rounded-sm " +
                                                        "px-2 py-3 text-left " +
                                                        "hover:bg-surface-subtle " +
                                                        "focus-visible:outline-2 " +
                                                        "focus-visible:outline-focus"
                                                    }>
                                                    {content}
                                                </button>
                                            ) : (
                                                <div data-slot="schedule-event"
                                                    className="grid gap-1 px-2 py-3">
                                                    {content}
                                                </div>
                                            )}
                                            <div className="flex flex-wrap gap-2 px-2">
                                                {event.taskId && onTaskSelect && (
                                                    <Button variant="ghost"
                                                        disabled={saving}
                                                        onClick={() =>
                                                            onTaskSelect(
                                                                event.taskId!,
                                                                event,
                                                            )}>
                                                        작업 상세
                                                    </Button>
                                                )}
                                                {onEventReschedule && (
                                                    <Button variant="outline"
                                                        disabled={saving}
                                                        onClick={() =>
                                                            beginReschedule(event)}>
                                                        일정 편집
                                                    </Button>
                                                )}
                                            </div>
                                            {eventEditing &&
                                                onEventReschedule && (
                                                <form onSubmit={(formEvent) =>
                                                    void submitReschedule(formEvent)}
                                                    className={"grid gap-2 rounded-sm " +
                                                        "border border-border p-3"}>
                                                    <label className="grid gap-1 text-xs">
                                                        시작 날짜
                                                        <input type="date"
                                                            aria-label={`${event.title} 시작 날짜`}
                                                            required
                                                            value={eventEditing.date}
                                                            disabled={saving}
                                                            onChange={(change) =>
                                                                updateEditing({
                                                                    date: change.target.value,
                                                                })}
                                                            className={"min-h-9 rounded-sm border " +
                                                                "border-border bg-surface px-2 text-sm"} />
                                                    </label>
                                                    <label className="grid gap-1 text-xs">
                                                        종료 날짜
                                                        <input type="date"
                                                            aria-label={`${event.title} 종료 날짜`}
                                                            value={eventEditing.endDate}
                                                            disabled={saving}
                                                            onChange={(change) =>
                                                                updateEditing({
                                                                    endDate: change.target.value,
                                                                })}
                                                            className={"min-h-9 rounded-sm border " +
                                                                "border-border bg-surface px-2 text-sm"} />
                                                    </label>
                                                    <label className="grid gap-1 text-xs">
                                                        시작 시간
                                                        <input type="time"
                                                            aria-label={`${event.title} 시작 시간`}
                                                            value={eventEditing.startTime}
                                                            disabled={saving}
                                                            onChange={(change) =>
                                                                updateEditing({
                                                                    startTime: change.target.value,
                                                                })}
                                                            className={"min-h-9 rounded-sm border " +
                                                                "border-border bg-surface px-2 text-sm"} />
                                                    </label>
                                                    <label className="grid gap-1 text-xs">
                                                        종료 시간
                                                        <input type="time"
                                                            aria-label={`${event.title} 종료 시간`}
                                                            value={eventEditing.endTime}
                                                            disabled={saving}
                                                            onChange={(change) =>
                                                                updateEditing({
                                                                    endTime: change.target.value,
                                                                })}
                                                            className={"min-h-9 rounded-sm border " +
                                                                "border-border bg-surface px-2 text-sm"} />
                                                    </label>
                                                    {rescheduleError && (
                                                        <p role="alert" className="m-0 text-sm text-danger">
                                                            {rescheduleError}
                                                        </p>
                                                    )}
                                                    <div className="flex flex-wrap gap-2">
                                                        <button ref={rescheduleButton}
                                                            type="submit"
                                                            disabled={saving}
                                                            className={"rounded-sm border border-border " +
                                                                "px-3 py-2 text-sm focus-visible:outline-2 " +
                                                                "focus-visible:outline-focus disabled:opacity-50"}>
                                                            {rescheduleError
                                                                ? "재시도" : "일정 저장"}
                                                        </button>
                                                        <button type="button"
                                                            disabled={saving}
                                                            onClick={cancelReschedule}
                                                            className={"rounded-sm px-3 py-2 text-sm " +
                                                                "focus-visible:outline-2 " +
                                                                "focus-visible:outline-focus disabled:opacity-50"}>
                                                            취소
                                                        </button>
                                                    </div>
                                                </form>
                                            )}
                                        </div>
                                    </li>
                                );
                            })}
                        </ul>
                    )}
                </div>
            </div>
        </section>
    );
}

export { CalendarScheduler };
export type {
    CalendarSchedule,
    CalendarScheduleReschedule,
    CalendarSchedulerProps,
};

function parseCalendarDate(value: string): Date {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (!match) throw new RangeError(`Invalid calendar date: ${value}`);

    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    const date = new Date(0);
    date.setFullYear(year, month - 1, day);
    date.setHours(12, 0, 0, 0);
    if (
        date.getFullYear() !== year ||
        date.getMonth() !== month - 1 ||
        date.getDate() !== day
    ) {
        throw new RangeError(`Invalid calendar date: ${value}`);
    }
    return date;
}

function formatCalendarDate(date: Date): string {
    const year = String(date.getFullYear()).padStart(4, "0");
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
}

export { parseCalendarDate, formatCalendarDate };
